using System;
using Outbreak.Contracts;
using Outbreak.Core;
using Outbreak.Persistence;
public static partial class Program
{
    private static void CheckDistributionCenterCases()
    {
        Check("Distribution-center courier delivers finite stock to a store and clerk replenishes its shelf",()=>{
            World world=EncounterScenarios.DistributionCenterTest();Require(world.DistributionCenters().Length==1 && world.DistributionCenters()[0].Couriers==1 && world.DistributionCenters()[0].AvailableMeals==24,"Center stock or staff assignment was not configured.");World copy=Documents.ParseSave(State(world));bool carried=false;for(int i=0;i<450 && world.ShelfAt(12,7).food<2;i++){world.Step();copy.Step();Require(State(world)==State(copy),"Center-to-store chain diverged after saving.");carried|=world.ActorAt(0).restockPhase==RestockPhase.Returning && world.ActorAt(0).carriedFood>1;Require(StorageRules.Count(world.StorageBoxAt(4,3),InventoryItem.Food)>=6,"Center courier removed its stock reserve.");}Require(carried && world.ShelfAt(12,7).food>=2 && StorageRules.Count(world.StorageBoxAt(4,3),InventoryItem.Food)<30 && world.FoodSupplies().RemainingMeals==32,"Center delivery failed physical transfer, clerk replenishment or food conservation.");
        });
        Check("Distribution-center membership preserves independent home destinations and schedules",()=>{
            World world=EncounterScenarios.DistributionCenterTest();world.TrySetCourierSchedule(0,7,12);ActorState before=world.ActorAt(0);Require(world.TryUnassignDistributionCourier(0),"Could not remove center membership.");ActorState after=world.ActorAt(0);after.distributionCenterId=before.distributionCenterId;Require(Documents.Encode(before)==Documents.Encode(after),"Unassignment rewrote home, route, cargo or shift.");Require(world.TryAssignDistributionCourier(0,183),"Could not reassign center.");world.Step();string busy=State(world);Require(!world.TryUnassignDistributionCourier(0) && !world.TryAssignDistributionCourier(0,183) && State(world)==busy,"Busy membership edit changed current cargo or task.");
        });
        Check("Center stock-box replacement and source overrides cannot invalidate assigned couriers",()=>{
            World world=EncounterScenarios.DistributionCenterTest();SaveDocument saved=world.Capture();WorldMap map=WorldMap.Restore(saved.map);map.SetStorageBox(new StorageBoxDocument{x=2,y=7,capacity=30,items=new ItemStackDocument[0]});saved.map=map.Capture();world=World.Restore(saved);string before=State(world);Require(!world.TryConfigureDistributionCenter(2,7) && !world.TrySetCourierSource(0,42,3) && State(world)==before,"Center stock/source changed underneath a bound courier.");Require(world.TryUnassignDistributionCourier(0) && world.TryConfigureDistributionCenter(2,7) && world.TryAssignDistributionCourier(0,183) && world.ActorAt(0).courierSourceBox==423,"Unassigned center stock could not be reconfigured safely.");Require(!world.TryConfigureStore(2,7) && !world.TryConfigureDistributionCenter(13,3),"Store crate and center stock claimed the same box.");
        });
        Check("Ordinary consumers cannot withdraw center stock while staff retain personal-meal access",()=>{
            World world=EncounterScenarios.DistributionCenterTest();world.TryClearCourierRoute(0);SaveDocument saved=world.Capture();saved.actors[0].hunger=80;saved.actors[0].carriedFood=0;world=World.Restore(saved);world.Step();Require(StorageRules.Count(world.StorageBoxAt(4,3),InventoryItem.Food)==30 && world.ActorAt(0).carriedFood==0,"Ordinary human bypassed distribution stock access.");world=EncounterScenarios.DistributionCenterTest();saved=world.Capture();saved.actors[0].hunger=80;saved.actors[0].carriedFood=0;world=World.Restore(saved);Run(world,6);Require(StorageRules.Count(world.StorageBoxAt(4,3),InventoryItem.Food)==27 && world.ActorAt(0).carriedFood==3,"Assigned center staff could not obtain a personal meal.");world.TrySetStorageDonations(4,3,false);Require(world.DistributionCenters()[0].AvailableMeals==0,"Donation block did not update available center stock.");
        });
        Check("Centers support different courier assignments and detached saved configurations",()=>{
            World world=EncounterScenarios.DistributionCenterTest();Require(world.TryConfigureDistributionCenter(42,3) && world.TryAssignDistributionCourier(0,222),"Could not designate or change to another center.");Require(world.DistributionCenters()[0].Couriers==0 && world.DistributionCenters()[1].Couriers==1 && world.ActorAt(0).assignedHouseId==183 && world.ActorAt(0).courierBoxes[0]==194,"Center change changed household or delivery destination.");SaveDocument saved=world.Capture();saved.distributionCenters[0].supplyBox=1;DistributionCenterOverview[] rows=world.DistributionCenters();rows[0].StockMeals=0;Require(world.DistributionCenters()[0].StockMeals==30 && State(Documents.ParseSave(State(world)))==State(world),"Center snapshots leaked mutable configuration or failed save round trip.");world.TryClearCourierRoute(0);Require(world.ActorAt(0).distributionCenterId==0,"Clearing courier route retained center binding.");Require(world.TryAssignDistributionCourier(0,183),"Could not assign center while waiting for destinations.");Run(world,6);Require(world.ActorAt(0).courierBoxes==null && world.ActorAt(0).restockPhase==RestockPhase.None && world.DistributionCenters()[0].ActiveTrips==0,"Courier without destinations started unrelated restocking work.");
        });
        Check("Distribution-center records validate legacy rules geometry roles and conversion cleanup",()=>{
            World world=EncounterScenarios.DistributionCenterTest();Action<Action<SaveDocument>> bad=change=>{SaveDocument saved=world.Capture();change(saved);Reject(()=>World.Restore(saved));};bad(s=>s.rulesVersion=EncounterRules.StoresVersion);bad(s=>s.distributionCenters[0].supplyBox=194);bad(s=>s.distributionCenters=new[]{s.distributionCenters[0],s.distributionCenters[0]});bad(s=>s.distributionCenters=null);bad(s=>s.actors[0].courierSourceBox=223);bad(s=>s.actors[0].distributionCenterId=999);bad(s=>s.actors[1].distributionCenterId=183);SaveDocument infected=world.Capture();infected.actors[0].turnAtTick=1;world=World.Restore(infected);world.Step();Require(world.ActorAt(0).species==Species.Zombie && world.ActorAt(0).distributionCenterId==0 && world.DistributionCenters()[0].Couriers==0,"Converted courier remained center staff.");SaveDocument old=EncounterScenarios.AssignedCourierTest().Capture();old.rulesVersion=EncounterRules.StoresVersion;world=World.Restore(old);Require(!world.DistributionCentersEnabled && world.StoresEnabled && !world.TryConfigureDistributionCenter(4,3),"Older store rules silently gained centers.");
        });
    }
}
